Import-Module ActiveDirectory

# Horario de inicio de sesión: logonHours son 21 bytes (168 h de la semana) y se guardan en UTC
function Set-Horario($sam, [int[]]$dias, [int]$inicio, [int]$horas) {
    $bytes  = New-Object byte[] 21
    $offset = [int][TimeZoneInfo]::Local.GetUtcOffset((Get-Date)).TotalHours
    foreach ($d in $dias) {
        for ($h = $inicio; $h -lt $inicio + $horas; $h++) {
            $utc = ($d * 24 + $h - $offset) % 168
            if ($utc -lt 0) { $utc += 168 }
            $bytes[[math]::Floor($utc / 8)] = $bytes[[math]::Floor($utc / 8)] -bor (1 -shl ($utc % 8))
        }
    }
    Set-ADUser $sam -Replace @{logonHours = [byte[]]$bytes}
}

New-ADOrganizationalUnit -Name "Eva3" -Path $dn

$areas = @(
    @{OU="Informática"; G="G_Informatica"; P="inf"; PC="PC-INF"; Dias=0..6; Ini=8; H=5},
    @{OU="Admin";       G="G_Admin";       P="adm"; PC="PC-ADM"; Dias=1..5; Ini=9; H=8},
    @{OU="Logistica";   G="G_Logistica";   P="log"; PC="PC-LOG"; Dias=1..6; Ini=8; H=7},
    @{OU="Mantención";  G="G_Mantencion";  P="man"; PC="PC-MAN"; Dias=0..6; Ini=8; H=6}
)

foreach ($a in $areas) {
    New-ADOrganizationalUnit -Name $a.OU -Path $raiz
    $ou = "OU=$($a.OU),$raiz"
    New-ADGroup -Name $a.G -GroupScope Global -GroupCategory Security -Path $ou
    foreach ($n in 1..2) {
        $sam = "$($a.P).usuario$n"
        New-ADUser -Name "Usuario$n $($a.OU)" -GivenName "Usuario$n" -Surname $a.OU `
            -SamAccountName $sam -UserPrincipalName "$sam@$dominio" -Path $ou `
            -AccountPassword $pass -Enabled $true -PasswordNeverExpires $true `
            -LogonWorkstations ("{0}0{1}" -f $a.PC, $n)
        Add-ADGroupMember -Identity $a.G -Members $sam
        Set-Horario $sam $a.Dias $a.Ini $a.H
    }
}

# Clave = nombre de la OU (igual que en $areas, con tildes); el nombre de la GPO va sin tildes
$reglas = @{
    "Informática" = @{GPO="GPO_Informatica"; Key="$polU\Explorer"; ValueName="NoControlPanel"; Value=1}
    "Admin"       = @{GPO="GPO_Admin";       Key="$polU\Explorer"; ValueName="NoRun";          Value=1}
    "Logistica"   = @{GPO="GPO_Logistica";   Key="$polU\System";   ValueName="DisableTaskMgr"; Value=1}
    "Mantención"  = @{GPO="GPO_Mantencion";  Key="HKCU\Software\Policies\Microsoft\Windows\System"; ValueName="DisableCMD"; Value=2}
}
foreach ($ou in $reglas.Keys) {
    $g = $reglas[$ou]
    New-GPO -Name $g.GPO -Comment "Politica del departamento $ou" | New-GPLink -Target "OU=$ou,$raiz"
    Set-GPRegistryValue -Name $g.GPO -Key $g.Key -ValueName $g.ValueName -Type DWord -Value $g.Value
}

